\coordinate (A) at (2,0);
\coordinate (X) at (1.2,0);
\draw[thick] (O) -- (P) node[midway, above left] {$r$};
\draw[dashed] (P) -- (X);
\fill (P) circle (1.5pt) node[above right] {$P(x,y)$};
\pic[draw, "$\theta$", angle radius=0.6cm, angle eccentricity=1.8] {angle = A--O--P};
\node[below left] at (O) {$O$};
